function renderGuidedApi(payload) {
  const guided = payload.run?.guided;
  $("#guidedApiPanel").hidden = !guided;
  if (!guided) return;
  const steps = guided.steps || [];
  const pending = steps.find(step => step.status === "waiting");
  const current = steps.find(step => step.status === "running");
  $("#guidedApiNext").disabled = !payload.running || !pending?.ready;
  $("#guidedApiMessage").textContent = guided.closed ? "Przebieg zakończony — wynik i raport poniżej." : pending ? `Gotowe: ${pending.title}. Kliknij Następny krok lub naciśnij F10.` : current ? `Wykonywanie: ${current.title}` : "Przygotowanie danych w tle — bez dodatkowej przeglądarki…";
  const labels = { waiting: "Czeka na uruchomienie", running: "W trakcie", passed: "PASS", failed: "FAIL", interrupted: "Przerwano" };
  $("#guidedApiSteps").innerHTML = steps.map((step, index) => `<article class="guided-api-step"><h4>${index + 1}. ${escapeHtml(step.title)} — ${escapeHtml(labels[step.status] || step.status)}</h4>${step.automatic ? "<p>Etap automatyczny.</p>" : ""}${step.requests.map(request => `<details><summary>${escapeHtml(request.method)} ${escapeHtml(request.path)} → ${escapeHtml(request.status ?? "błąd")}</summary><pre>${escapeHtml(JSON.stringify(request, null, 2))}</pre></details>`).join("")}${step.error ? `<pre class="guided-api-error">${escapeHtml(step.error)}</pre>` : ""}</article>`).join("");
}

async function nextGuidedApiStep() {
  const run = state.status?.run;
  const step = run?.guided?.steps.find(item => item.status === "waiting" && item.ready);
  if (!state.status?.running || !step || $("#guidedApiNext").disabled) return;
  $("#guidedApiNext").disabled = true;
  try { await api("/api/guided/next", { method: "POST", body: JSON.stringify({ runId: run.id, stepId: step.id }) }); }
  catch (error) { $("#guidedApiMessage").textContent = error.message; }
}

