function resultBadge(value) {
  const safe = escapeHtml(value || "BRAK");
  const css = String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, "-");
  return `<span class="data-badge ${css}">${safe}</span>`;
}

